jQuery(document).ready(function(){let topics=null;const boldify=(str,reg)=>{return str.replace(reg,(a)=>`<span class='highlighted-word'>${a}</span>`)};function showSearchResults(topics){let content='';for(let i=0;i<topics.length;i++){content+='<li>'+'<a href="'+window.location.origin+topics[i].path+'"><img src="'+topics[i].image+'" alt="'+topics[i].title+'" class="topic-image" /></a>'+'<div>'+'<h2><a href="'+window.location.origin+topics[i].path+'">'+topics[i].title+'</a></h2>'+'<p class="short-content">'+topics[i].content+'</p> '+'</li>'+'</div>'}
document.getElementById('results-count').innerHTML=topics.length;document.getElementById('search-results-count__wrapper').style.display='block';if(topics.length>0){document.getElementById('search-results').innerHTML=content;document.getElementById('search-results__wrapper').style.display='block';document.getElementById('search-nothing__wrapper').style.display='none'}else{document.getElementById('search-results__wrapper').style.display='none';document.getElementById('search-nothing__wrapper').style.display='block'}}
const searchMessageTextLength=320;function getCuttedContentIfNeed(value,match){if(!match||match.index<(searchMessageTextLength-match[0].length)){return value.slice(0,searchMessageTextLength)+(value.length>searchMessageTextLength?'...':'')}else if((match.index+searchMessageTextLength)>value.length){return'... '+value.slice(value.length-searchMessageTextLength)}else{let regExpSentenceStart='[.!?]';let stringBeforeNeeded=value.slice(0,match.index);const reg=new RegExp(regExpSentenceStart,"ig");let stringEndsMatches=stringBeforeNeeded.matchAll(reg);let stringEndsMatchesArray=[...stringEndsMatches];let startIndex=match.index;if(stringEndsMatchesArray.length>0){startIndex=stringEndsMatchesArray[stringEndsMatchesArray.length-1].index+1}
return'...'+value.slice(startIndex,startIndex+searchMessageTextLength)+' ...'}}
function updateTopicsData(){const url=window.location.origin+'/support/search/topics-data.json';jQuery.ajax({url:url,type:'GET',async:!1,dataType:"json",success:function(data){try{topics=JSON.parse(data)}catch(e){topics=data}}})}
function search(value){document.getElementById('search-word').textContent=value;if(topics===null){updateTopicsData()}
let highlightedTopics=searchAndHighlight(value,JSON.parse(JSON.stringify(topics)));showSearchResults(highlightedTopics)}
function initSearch(){let searchButtons=document.querySelectorAll('.support-search-button');for(let i=0;i<searchButtons.length;i++){searchButtons[i].addEventListener('click',function(e){let searchingValue=this.parentElement.querySelector('.support-search-input').value;search(searchingValue)})}
let searchForms=document.querySelectorAll('.search-form');for(let i=0;i<searchForms.length;i++){searchForms[i].addEventListener('submit',function(e){e.preventDefault();let searchingValue=this.querySelector('.support-search-input').value;search(searchingValue)})}}
function searchAndHighlight(value,topics){let trimmedValue=value.replaceAll(/\s+/g,' ').trim();let regExpFullSentence='\\b(?:'+trimmedValue+')\\b'
let regExp='\\b(?:'+trimmedValue.replaceAll(' ','|')+')\\b';const reg=new RegExp(regExp,"ig");const regFullSentence=new RegExp(regExpFullSentence,"ig");let topicsWithoutTerms=[];let searchInTerms=topics.filter(topic=>{let isMatched=topic.terms.match(reg);if(isMatched){topic.content=getCuttedContentIfNeed(topic.content,!1)}else{topicsWithoutTerms.push(topic)}
return isMatched});let searchResult=topicsWithoutTerms.filter(topic=>{let contentMatch=regFullSentence.exec(topic.content)||reg.exec(topic.content);let isMatched=contentMatch||topic.title.match(reg);if(isMatched){let content=getCuttedContentIfNeed(topic.content,contentMatch);topic.content=boldify(content,reg);topic.title=boldify(topic.title,reg)}
return isMatched});searchInTerms.push(...searchResult);searchInTerms.sort((a,b)=>{const aTitleMatches=(a.title.match(reg)||[]).length;const bTitleMatches=(b.title.match(reg)||[]).length;return bTitleMatches-aTitleMatches});return searchInTerms}
function initSuggestions(){const inputFields=document.querySelectorAll('.support-search-input');inputFields.forEach(input=>{const suggestionsContainer=input.parentElement.querySelector('.search-suggestions');input.addEventListener('input',function(){const value=this.value.trim().toLowerCase();suggestionsContainer.innerHTML='';if(!topics){updateTopicsData()}
if(!value||!topics)return;const filtered=topics.filter(t=>t.title.toLowerCase().includes(value)||(t.terms&&t.terms.toLowerCase().includes(value))).slice(0,5);filtered.forEach(topic=>{const li=document.createElement('li');li.classList.add('suggestion-item');const excerpt=topic.content.length>100?topic.content.slice(0,100)+'...':topic.content;li.innerHTML=`
                        <a href="${window.location.origin + topic.path}" class="suggestion-content">
                            <img src="${topic.image}" alt="${topic.title}" class="suggestion-image" />
                            <div class="suggestion-text">
                                <h3>${topic.title}</strong>
                                <p>${excerpt}</p>
                            </div>
                        </a>
                    `;suggestionsContainer.appendChild(li)})});input.addEventListener('blur',function(){setTimeout(()=>suggestionsContainer.innerHTML='',150)})})}
initSuggestions();initSearch();const queryString=window.location.search;const urlParams=new URLSearchParams(queryString);if(urlParams.has('search')){search(urlParams.get('search'))}})